// Generated by `dart run drift_dev make-migrations`, then filled in.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:huenote/core/database/app_database.dart';

import 'generated/schema.dart';
import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() => verifier = SchemaVerifier(GeneratedHelper()));

  group('every migration path produces the declared schema', () {
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      for (final toVersion in versions.skip(i + 1)) {
        test('$fromVersion -> $toVersion', () async {
          final schema = await verifier.schemaAt(fromVersion);
          final db = AppDatabase(schema.newConnection());
          await verifier.migrateAndValidate(db, toVersion);
          await db.close();
        });
      }
    }
  });

  test('v1 -> v2 keeps notes and labels; purged defaults to 0', () async {
    const oldNote = v1.NotesData(
      id: 'n1',
      type: 0,
      title: 'Keep me',
      body: 'body',
      color: 3,
      isPinned: 1,
      isArchived: 0,
      isLocked: 0,
      reminderAllDay: 0,
      statusBarPinned: 0,
      createdAt: 1,
      updatedAt: 2,
      baseVersion: 0,
      dirty: 1,
      myPermission: 0,
    );
    const expectedNote = v2.NotesData(
      id: 'n1',
      type: 0,
      title: 'Keep me',
      body: 'body',
      color: 3,
      isPinned: 1,
      isArchived: 0,
      isLocked: 0,
      reminderAllDay: 0,
      statusBarPinned: 0,
      createdAt: 1,
      updatedAt: 2,
      baseVersion: 0,
      dirty: 1,
      myPermission: 0,
      purged: 0,
    );
    const oldLabel = v1.ColorLabelsData(
      color: 0,
      label: 'Work',
      updatedAt: 1,
      dirty: 1,
      baseVersion: 0,
    );
    const expectedLabel = v2.ColorLabelsData(
      color: 0,
      label: 'Work',
      updatedAt: 1,
      dirty: 1,
      baseVersion: 0,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: AppDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insertAll(oldDb.notes, [oldNote])
          ..insertAll(oldDb.colorLabels, [oldLabel]);
      },
      validateItems: (newDb) async {
        expect(await newDb.select(newDb.notes).get(), [expectedNote]);
        expect(await newDb.select(newDb.colorLabels).get(), [expectedLabel]);
      },
    );
  });
}
